pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(address actor, uint256 amount, uint256 futureTime) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1 wei, 1 ether);
        futureTime = bound(futureTime, block.timestamp + 1, block.timestamp + 365 days);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(futureTime);

        // General rule: after Put(t) with t > now, the caller's recorded unlockTime equals t.
        assertTrue(c.Acc(actor).unlockTime == futureTime, "unlockTime must equal the requested future time");
    }
}

