pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, Log} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(new Log())); }

    function testFuzz_property(uint256 amount, uint256 futureTime, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        amount = bound(amount, 1 ether, 1000 ether);
        futureTime = bound(futureTime, block.timestamp + 1, block.timestamp + 365 days);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(futureTime);

        // Funds locked until futureTime: immediate Collect must fail.
        vm.prank(actor);
        (bool s, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", amount));
        assertTrue(!s, "Collect before unlockTime must revert");
    }
}

